import numpy as np

def derivative(f, x, h=1e-5):
    # đạo hàm số học: độ dốc của f tại x (sai phân trung tâm)
    return (f(x + h) - f(x - h)) / (2 * h)

print(derivative(lambda x: x ** 2, 3))        # ~6  (vì (x^2)' = 2x)

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

print(round(derivative(sigmoid, 0), 4))        # 0.25

# gradient: véc-tơ các đạo hàm riêng
def f(x, y):
    return x ** 2 + 3 * y ** 2

def grad(x, y):
    return np.array([2 * x, 6 * y])           # df/dx, df/dy

print(grad(1, 2))

