import numpy as np

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def sigmoid_prime(x):
    s = sigmoid(x)
    return s * (1 - s)

print(round(float(sigmoid_prime(0)), 2))
print(round(float(sigmoid_prime(2)), 4))
